import {normalizeAnswer} from './catalog.js';
const day=t=>new Date(t).toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'});
export const topicMastered=r=>!!r&&r.independentCorrect>=4&&r.independentDays?.length>=3&&r.sessions?.length>=2&&r.unprompted>=1&&r.novel>=1&&r.lastIndependentOK===true&&accuracy(r)>=.8;
export const accuracy=r=>{let a=(r?.recent||[]).filter(e=>e.independent).slice(-16);return a.length?a.filter(e=>e.ok).length/a.length:0};
export function profileFor(state,id){return state.profile?.topics?.[id]||null}
export function advancedReady(state,id){let r=profileFor(state,id);return !!r&&r.lastIndependentOK===true&&r.independentCorrect>=4&&r.independentDays.length>=2&&accuracy(r)>=.85&&r.unprompted>=1}
export function recordEvent(state,q,{id,runId,quality,format,support=0,checkpoint=false,novel=false,now=Date.now(),elapsed=0,viewedSolution=false}){
 state.profile??={version:1,topics:{},events:[],diagnostics:[]};let p=state.profile;if(p.events.some(e=>e.id===id))return false;
 const independent=quality>=0&&!checkpoint&&format!=='recall'&&support===0&&!viewedSolution;
 let e={id,qid:q.id,topic:q.topicId||q.lesson,ch:q.ch,runId,quality,format,support,checkpoint,novel,at:now,elapsed:Math.max(0,elapsed),viewedSolution,independent,ok:quality>=2};
 p.events.push(e);p.events=p.events.slice(-2000);let old=p.topics[e.topic]||{attempts:0,independentCorrect:0,independentDays:[],sessions:[],unprompted:0,novel:0,assisted:0,selfRatings:0,failures:0,recent:[]},r={...old,independentDays:[...old.independentDays],sessions:[...old.sessions],recent:[...old.recent.filter(x=>x.independent).slice(-15),...old.recent.filter(x=>!x.independent).slice(-15),e].sort((a,b)=>a.at-b.at),attempts:old.attempts+1};
 if(format==='recall')r.selfRatings++;else if(support>0||viewedSolution)r.assisted++;
 if(independent){r.lastIndependentOK=e.ok;if(e.ok){r.independentCorrect++;if(!r.independentDays.includes(day(now)))r.independentDays.push(day(now));if(!r.sessions.includes(runId))r.sessions.push(runId);if(['short','transfer'].includes(format))r.unprompted++;if(novel||q.level>=3)r.novel++}else r.failures++}
 r.independentDays=r.independentDays.slice(-60);r.sessions=r.sessions.slice(-100);r.updated=now;p.topics[e.topic]=r;return true;
}
export function markDiagnostic(state,session,now=Date.now()){if(session.mode!=='diagnostic')return;state.profile??={version:1,topics:{},events:[],diagnostics:[]};if(state.profile.diagnostics.some(d=>d.id===session.id))return;let byChapter=[0,1,2,3].map(ch=>{let rows=session.cards.filter(c=>c.ch===ch&&c.status==='answered');return {ch,answered:rows.length,correct:rows.filter(c=>c.quality>=2&&!(c.support>0)).length}});state.profile.diagnostics.push({id:session.id,date:now,byChapter});state.profile.diagnostics=state.profile.diagnostics.slice(-20)}
export function cleanProfile(raw,qids,topics){let p={version:1,topics:{},events:[],diagnostics:[]};if(!raw||typeof raw!=='object')return p;let keys=['attempts','independentCorrect','unprompted','novel','assisted','selfRatings','failures','updated'];for(let id of topics){let r=raw.topics?.[id];if(!r||keys.some(k=>!Number.isFinite(r[k]??0)||(r[k]??0)<0))continue;p.topics[id]={...Object.fromEntries(keys.map(k=>[k,Math.min(1e8,r[k]||0)])),independentDays:[...new Set((Array.isArray(r.independentDays)?r.independentDays:[]).filter(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)))].slice(-60),sessions:[...new Set((Array.isArray(r.sessions)?r.sessions:[]).filter(s=>typeof s==='string'&&s.length<=100))].slice(-100),lastIndependentOK:r.lastIndependentOK===true,recent:[]}}
 if(Array.isArray(raw.events))for(let e of raw.events.slice(-2000)){if(!qids.includes(e.qid)||!topics.includes(e.topic)||typeof e.id!=='string'||e.id.length>180||typeof e.runId!=='string'||!Number.isFinite(e.at)||![0,1,2,3].includes(e.quality))continue;let row={id:e.id,qid:e.qid,topic:e.topic,ch:e.ch,runId:e.runId,quality:e.quality,format:['mcq','math','short','transfer','recall'].includes(e.format)?e.format:'mcq',support:Number.isFinite(e.support)?Math.max(0,e.support):0,checkpoint:!!e.checkpoint,novel:!!e.novel,at:e.at,elapsed:Number.isFinite(e.elapsed)?Math.max(0,e.elapsed):0,viewedSolution:!!e.viewedSolution,independent:e.independent===true,ok:e.quality>=2};if(p.events.some(x=>x.id===row.id))continue;p.events.push(row)}
 for(let [id,r] of Object.entries(p.topics))r.recent=[...p.events.filter(e=>e.topic===id&&e.independent).slice(-16),...p.events.filter(e=>e.topic===id&&!e.independent).slice(-16)].sort((a,b)=>a.at-b.at);if(Array.isArray(raw.diagnostics))p.diagnostics=raw.diagnostics.filter(d=>typeof d.id==='string'&&Number.isFinite(d.date)&&Array.isArray(d.byChapter)).map(d=>({id:d.id,date:d.date,byChapter:d.byChapter.filter(x=>Number.isInteger(x.ch)&&x.ch>=0&&x.ch<4&&Number.isInteger(x.answered)&&x.answered>=0&&Number.isInteger(x.correct)&&x.correct>=0&&x.correct<=x.answered)})).slice(-20);return p;
}
export function gradeShort(text,q){let value=normalizeAnswer(text);return {valid:value.length>0&&value.length<1000,ok:value.length>0&&(q.shortAnswers||[]).some(a=>normalizeAnswer(a)===value)} }
export function prerequisite(q,qs){let mapping={performance:'v3-1-1',http:'l9q0',transport:'l15q0',addressing:'l21q1',routing:'l26q0'};let id=mapping[q.cluster]||['l0q0','l7q1','l14q0','v3-4-1'][q.ch];return qs.find(x=>x.id===id)||qs.find(x=>x.ch===q.ch&&x.level===1)}
export function feedbackReason(q,selected){if(selected===null||selected===-1)return 'Chưa biết giúp xác định chỗ cần học. '+q.explain;return q.distractorReasons?.[selected]||q.explain}
export function topicStatus(state,topic){let r=profileFor(state,topic);if(!r)return 'Chưa đánh giá';if(topicMastered(r))return 'Vững';if(r.lastIndependentOK===false||accuracy(r)<.5&&r.recent.some(e=>e.independent))return 'Cần củng cố';return 'Đang học'}
